contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, bool repayDirect_, bool isCallback_) public payable {
        require(loanToCollateral_ != 0, "div by zero");
        require(duration_ <= 365 days, "duration too large");
        require(interest_ <= 1e18, "interest too large");

        c.requestLoan(amount_, interest_, loanToCollateral_, duration_); if (__ESBMC_reverted()) return;

        uint256 returnedLoanID;
        uint256 loanID = c.clearRequest(0, repayDirect_, isCallback_); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            assert(false);
            return;
        } else {
            returnedLoanID = loanID;
        }

        assert(returnedLoanID == 0);
    }

    receive() external payable {}
}

