// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, bool repayDirect_, bool isCallback_) internal {
        vm.assume(loanToCollateral_ != 0);
        duration_ = bound(duration_, 0, 365);
        vm.assume(interest_ <= 1e18);
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {} catch { return; }
        uint256 returnedLoanID;
        try c.clearRequest(0, repayDirect_, isCallback_) returns (uint256 loanID) {
            returnedLoanID = loanID;
        } catch {
            assert(false);
            return;
        }
        assertTrue(returnedLoanID == 0);
    }

    function testFuzz_run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, bool repayDirect_, bool isCallback_) public {
        _run(amount_, interest_, loanToCollateral_, duration_, repayDirect_, isCallback_);
    }

    receive() external payable {}
}
